mapper.insert:
MERGE INTO MOBILE_PUSH_LOGIN_TOKEN AS target USING (SELECT #{emplNo} AS EMPL_NO) AS source ON (target.EMPL_NO = source.EMPL_NO)
WHEN MATCHED THEN UPDATE SET LOGIN_TOKEN = #{refreshToken}, END_DATE = #{refreshExpiration}
WHEN NOT MATCHED THEN INSERT (EMPL_NO, LOGIN_TOKEN, END_DATE) VALUES (#{emplNo}, #{refreshToken}, #{refreshExpiration});

mapper.select:
SELECT EMPL_NO, END_DATE
FROM MOBILE_PUSH_LOGIN_TOKEN
WHERE LOGIN_TOKEN = #{refreshToken}

mapper.insert:
UPDATE MOBILE_PUSH_LOGIN_TOKEN
SET
LOGIN_TOKEN = #{refreshToken},
END_DATE = #{refreshExpiration}
WHERE
EMPL_NO = #{emplNo}
